{"l":9675,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","q":"Hvad betyder 'to strike while the iron is hot'?","o":["at strejke","at stryge tøj","at være vred","at smede, mens jernet er varmt"],"a":"at smede, mens jernet er varmt","r":"Udtrykket betyder at udnytte en god mulighed med det samme."},
{"l":9686,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","q":"Hvad betyder 'to have an axe to grind'?","o":["at have en personlig dagsorden","at hugge brænde","at være vred i dag","at slibe en kniv"],"a":"at have en personlig dagsorden","r":"Udtrykket betyder at have egne motiver."},
